mapper.select:
SELECT q.*, c.name as category_name, u.nickname as creator_name, t.id as tag_id, t.name as tag_name, t.color as tag_color FROM question q LEFT JOIN category c ON q.category_id = c.id LEFT JOIN sys_user u ON q.created_by = u.id LEFT JOIN question_tag qt ON q.id = qt.question_id LEFT JOIN tag t ON qt.tag_id = t.id WHERE q.deleted = 0
AND (q.title LIKE CONCAT('%', #{query.keyword}, '%') OR q.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND q.category_id = #{query.categoryId}
AND q.difficulty = #{query.difficulty}
AND q.source LIKE CONCAT('%', #{query.source}, '%')
AND q.status = #{query.status}
AND q.id IN ( SELECT question_id FROM question_tag WHERE tag_id IN
#{tagId}
)
ORDER BY q.is_top DESC,
q.view_count q.like_count q.created_at
ASC DESC
